//! The seeded nodes in the example documents must give the same output as
//! in NodeBox 3.
//!
//! `nodebox3_examples.txt` holds what NodeBox 3 produced for each case. It is
//! generated by `NodeBox3Dump.java` (see that file for how to run it).
//!
//! Where the Rust evaluator renders the example, the node is evaluated in its
//! document. Where it cannot yet (fonts, CSV files, the polygon node), the
//! node's operation is called with the inputs NodeBox 3 gave it, which are in
//! the fixture too.

use std::collections::HashMap;
use std::sync::Arc;

use nodebox_core::eval::{evaluate_network, NodeOutput};
use nodebox_core::geometry::{Contour, Path, PathPoint, Point, PointType};
use nodebox_core::node::templates::{create_node_from_template, NODE_TEMPLATES};
use nodebox_core::node::{Node, NodeLibrary};
use nodebox_core::ops::math::random_numbers;
use nodebox_core::ops::{scatter, wiggle, WiggleScope};
use nodebox_core::platform::{Platform, ProjectContext, TestPlatform};
use nodebox_core::Value;

const EXAMPLES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../../examples/");

/// Seeded nodes that the Rust evaluator renders in their document.
const IN_DOCUMENT: &[&str] = &[
    "01 Basics/01 Shape/09 Binary Operation/09 Binary Operation.ndbx::/random_numbers1",
    "01 Basics/01 Shape/10 Sorting/10 Sorting.ndbx::/scatter1",
    "01 Basics/03 Numbers/01 Create Numbers/01 Create Numbers.ndbx::/random_numbers1",
    "01 Basics/03 Numbers/04 Random/04 Random.ndbx::/random_numbers1",
    "01 Basics/03 Numbers/05 Make Numbers/05 Make Numbers.ndbx::/shuffle1",
    "01 Basics/05 String/Name Generator/Name Generator.ndbx::/pick1",
    "01 Basics/05 String/Name Generator/Name Generator.ndbx::/pick2",
    "01 Basics/05 String/Name Generator/Name Generator.ndbx::/pick3",
    "01 Basics/05 String/Name Generator/Name Generator.ndbx::/pick4",
    "01 Basics/06 Lists/Compare/Compare.ndbx::/random_numbers1",
    "02 Topics/Data Visualisation/03 Piechart/03 Piechart.ndbx::/random_numbers1",
    "02 Topics/Generative Design/Invader/Invader.ndbx::/random_numbers1",
];

const TILLING: &str = "01 Basics/01 Shape/13 Tilling/13 Tilling.ndbx";
const ZIPMAP: &str = "02 Topics/Data Visualisation/04 Zipmap/04 Zipmap.ndbx";
const LOGO: &str = "02 Topics/Generative Design/Animated Logo/Animated Logo.ndbx";

/// A value as NodeBox 3 printed it; numbers as f64 bits.
#[derive(Debug, PartialEq)]
enum Item {
    Path(Vec<(bool, Vec<(u8, u64, u64)>)>),
    Float(u64),
    Int(i64),
    String(String),
    Point(u64, u64),
}

fn fixture() -> HashMap<String, Vec<Item>> {
    let text = include_str!("nodebox3_examples.txt");
    let mut cases: HashMap<String, Vec<Item>> = HashMap::new();
    let mut current = String::new();
    let f = |s: &str| s.parse::<f64>().unwrap().to_bits();
    for line in text.lines() {
        if let Some(case) = line.strip_prefix("# ") {
            current = case.to_string();
            cases.insert(current.clone(), Vec::new());
            continue;
        }
        let items = cases.get_mut(&current).unwrap();
        let (kind, rest) = line.split_once(' ').unwrap_or((line, ""));
        match kind {
            "path" => items.push(Item::Path(Vec::new())),
            "contour" => {
                let mut tokens = rest.split(' ');
                let closed = tokens.next() == Some("closed");
                let points = tokens
                    .map(|t| {
                        let (kind, xy) = t.split_once(':').unwrap();
                        let (x, y) = xy.split_once(',').unwrap();
                        (kind.parse().unwrap(), f(x), f(y))
                    })
                    .collect();
                match items.last_mut() {
                    Some(Item::Path(contours)) => contours.push((closed, points)),
                    _ => panic!("contour outside a path"),
                }
            }
            "float" => items.push(Item::Float(f(rest))),
            "int" => items.push(Item::Int(rest.parse().unwrap())),
            "string" => items.push(Item::String(rest.to_string())),
            "point" => {
                let (x, y) = rest.split_once(',').unwrap();
                items.push(Item::Point(f(x), f(y)));
            }
            _ => panic!("unexpected line: {line}"),
        }
    }
    cases
}

/// NodeBox 3's point types: 1 line, 2 curve, 3 curve data.
fn path_item(path: &Path) -> Item {
    Item::Path(
        path.contours
            .iter()
            .map(|c| {
                let points = c
                    .points
                    .iter()
                    .map(|p| {
                        let kind = match p.point_type {
                            PointType::LineTo => 1,
                            PointType::CurveTo => 2,
                            PointType::CurveData => 3,
                            _ => 0,
                        };
                        (kind, p.point.x.to_bits(), p.point.y.to_bits())
                    })
                    .collect();
                (c.closed, points)
            })
            .collect(),
    )
}

fn point_item(p: &Point) -> Item {
    Item::Point(p.x.to_bits(), p.y.to_bits())
}

fn items(output: &NodeOutput) -> Vec<Item> {
    match output {
        NodeOutput::Path(p) => vec![path_item(p)],
        NodeOutput::Paths(ps) => ps.iter().map(path_item).collect(),
        NodeOutput::Float(v) => vec![Item::Float(v.to_bits())],
        NodeOutput::Floats(vs) => vs.iter().map(|v| Item::Float(v.to_bits())).collect(),
        NodeOutput::Int(v) => vec![Item::Int(*v)],
        NodeOutput::Ints(vs) => vs.iter().map(|v| Item::Int(*v)).collect(),
        NodeOutput::String(v) => vec![Item::String(v.clone())],
        NodeOutput::Strings(vs) => vs.iter().map(|v| Item::String(v.clone())).collect(),
        NodeOutput::Point(p) => vec![point_item(p)],
        NodeOutput::Points(ps) => ps.iter().map(point_item).collect(),
        other => panic!("unexpected output {other:?}"),
    }
}

/// The NodeBox 3 path back as a Rust path.
fn to_path(item: &Item) -> Path {
    let Item::Path(contours) = item else { panic!("not a path: {item:?}") };
    Path::from_contours(
        contours
            .iter()
            .map(|(closed, points)| {
                let points = points
                    .iter()
                    .map(|&(kind, x, y)| {
                        let (x, y) = (f64::from_bits(x), f64::from_bits(y));
                        match kind {
                            2 => PathPoint::curve_to(x, y),
                            3 => PathPoint::curve_data(x, y),
                            _ => PathPoint::line_to(x, y),
                        }
                    })
                    .collect();
                Contour::from_points(points, *closed)
            })
            .collect(),
    )
}

/// Gives parsed nodes the ports of their prototype, as the app does on load.
fn resolve_ports(node: &mut Node, lib: &NodeLibrary) {
    if let Some(prototype) = &node.prototype {
        if let Some(template) = NODE_TEMPLATES.iter().find(|t| t.prototype == prototype) {
            let template_node = create_node_from_template(template, lib, Point::ZERO);
            let mut inputs = template_node.inputs;
            for port in &mut inputs {
                if let Some(parsed) = node.inputs.iter().find(|p| p.name == port.name) {
                    port.value = parsed.value.clone();
                }
            }
            node.inputs = inputs;
            node.output_type = template_node.output_type;
            node.output_range = template_node.output_range;
        }
    }
    for child in &mut node.children {
        resolve_ports(child, lib);
    }
}

fn load(example: &str) -> NodeLibrary {
    let mut library = nodebox_core::ndbx::parse_file(format!("{EXAMPLES}{example}")).unwrap();
    let temp = NodeLibrary::new("_temp");
    for child in &mut library.root.children {
        resolve_ports(child, &temp);
    }
    library
}

/// A port value of a root-level node, as set in the document.
fn port(library: &NodeLibrary, node: &str, name: &str) -> Value {
    let node = library.root.children.iter().find(|n| n.name == node).unwrap();
    node.input(name).unwrap().value.clone()
}

fn assert_same(case: &str, expected: &[Item], got: &[Item]) {
    assert_eq!(got.len(), expected.len(), "{case}: number of values");
    for (i, (g, e)) in got.iter().zip(expected).enumerate() {
        assert_eq!(g, e, "{case}: value {i}");
    }
}

#[test]
fn seeded_nodes_in_examples_match_nodebox_3() {
    let fixture = fixture();
    for &case in IN_DOCUMENT {
        let (example, node) = case.split_once("::/").unwrap();
        let mut library = load(example);
        library.root.rendered_child = Some(node.to_string());
        let platform: Arc<dyn Platform> = Arc::new(TestPlatform::new());
        let (_, output, errors) = evaluate_network(&library, &platform, &ProjectContext::new_unsaved());
        assert!(errors.is_empty(), "{case}: {errors:?}");
        assert_same(case, &fixture[case], &items(&output));
    }
}

#[test]
fn seeded_operations_match_nodebox_3_on_its_inputs() {
    let fixture = fixture();
    let case = |example: &str, node: &str| format!("{example}::/{node}");
    let int = |example: &str, node: &str| match fixture[&case(example, node)][..] {
        [Item::Int(v)] => v,
        _ => panic!("{node} is not one int"),
    };
    let float = |example: &str, node: &str| match fixture[&case(example, node)][..] {
        [Item::Float(v)] => f64::from_bits(v),
        _ => panic!("{node} is not one float"),
    };

    // Wiggle on the polygons NodeBox 3 drew (Rust's polygon node differs).
    let library = load(TILLING);
    for (polygon, node) in [("polygon1", "wiggle1"), ("polygon2", "wiggle2")] {
        let shape = to_path(&fixture[&case(TILLING, polygon)][0]);
        let scope = WiggleScope::from_str(port(&library, node, "scope").as_string().unwrap());
        let offset = *port(&library, node, "offset").as_point().unwrap();
        let seed = port(&library, node, "seed").as_int().unwrap();
        let got = path_item(&wiggle(&shape, scope, offset, seed));
        assert_same(&case(TILLING, node), &fixture[&case(TILLING, node)], &[got]);
    }

    // Scatter, with the album count NodeBox 3 read from the CSV file.
    let library = load(ZIPMAP);
    let shape = to_path(&fixture[&case(ZIPMAP, "ellipse1")][0]);
    let amount = int(ZIPMAP, "count2") as usize;
    let seed = port(&library, "scatter1", "seed").as_int().unwrap();
    let got: Vec<Item> = scatter(&shape, amount, seed).iter().map(point_item).collect();
    assert_same(&case(ZIPMAP, "scatter1"), &fixture[&case(ZIPMAP, "scatter1")], &got);

    // Random numbers, with the point counts of NodeBox 3's text outlines and
    // the start and end it computed from the frame.
    let library = load(LOGO);
    let cases = [
        ("random_numbers1", "count1", Some("negate1"), Some("subtract1")),
        ("random_numbers2", "count2", None, None),
        ("random_numbers3", "count3", Some("subtract1"), Some("negate1")),
    ];
    for (node, count, start, end) in cases {
        let value = |from: Option<&str>, name| match from {
            Some(n) => float(LOGO, n),
            None => port(&library, node, name).as_float().unwrap(),
        };
        let amount = int(LOGO, count) as usize;
        let seed = port(&library, node, "seed").as_int().unwrap();
        let got: Vec<Item> = random_numbers(amount, value(start, "start"), value(end, "end"), seed)
            .iter()
            .map(|v| Item::Float(v.to_bits()))
            .collect();
        assert_same(&case(LOGO, node), &fixture[&case(LOGO, node)], &got);
    }
}
